const CACHE='cognitive-care-ner-v0.12.0';
const APP_SHELL=['./','./index.html','./config.js?v=0.12.0','./styles.css?v=0.12.0','./avatar.css?v=0.12.0','./phase1.css?v=0.12.0','./phase2.css?v=0.12.0','./phase3.css?v=0.12.0','./phase4.css?v=0.12.0','./multilingual.css?v=0.12.0','./sequence-game.css?v=0.12.0','./sorting-game.css?v=0.12.0','./category-game.css?v=0.12.0','./pattern-game.css?v=0.12.0','./spot-difference-game.css?v=0.12.0','./routine-game.css?v=0.12.0','./multilingual.js?v=0.12.0','./regional-language-runtime.js?v=0.12.0','./regional-language-feedback.js?v=0.12.0','./adaptive-engine.js?v=0.12.0','./core-boot.js?v=0.12.0','./game-controls.js?v=0.12.0','./routine-game.js?v=0.12.0','./notification-bridge.js?v=0.12.0','./momo-voice.js?v=0.12.0','./ui-upgrade.js?v=0.12.0','./ui-failsafe.js?v=0.12.0','./security-center.js?v=0.12.0','./usability-validation.js?v=0.12.0','./production-hardening.js?v=0.12.0','./data-bridge.js?v=0.12.0','./manifest.webmanifest'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(APP_SHELL)).catch(()=>{}));self.skipWaiting()});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;const u=new URL(e.request.url);if(u.origin!==self.location.origin)return;const asset=u.pathname.endsWith('.html')||u.pathname.endsWith('.js')||u.pathname.endsWith('.css')||u.pathname==='/'||u.pathname.endsWith('.webmanifest');if(asset){e.respondWith(fetch(e.request,{cache:'no-store'}).then(r=>{if(r?.ok){const c=r.clone();caches.open(CACHE).then(x=>x.put(e.request,c)).catch(()=>{})}return r}).catch(()=>caches.match(e.request).then(x=>x||caches.match('./index.html'))));return}e.respondWith(caches.match(e.request).then(c=>c||fetch(e.request).then(r=>{const cp=r.clone();caches.open(CACHE).then(x=>x.put(e.request,cp)).catch(()=>{});return r}).catch(()=>caches.match('./index.html'))))});
